SQLContext resolves outer CTE column as ambiguous with table scoped inside CTE body
### Checks

- [x] I have checked that this issue has not already been reported.
- [x] I have confirmed this bug exists on the [latest version](https://crates.io/crates/polars) of Polars.

### Reproducible example

```rust
use expect_test::{expect, Expect};
use polars::prelude::*;
use polars_sql::SQLContext;
use std::fmt::Debug;

fn check<T: Debug>(actual: T, expect: Expect) {
    let actual = format!("{actual:?}");
    expect.assert_eq(&actual);
}

fn collect_sql(query: &str) -> PolarsResult<DataFrame> {
    let left_dataframe = DataFrame::new_infer_height(vec![
        Column::new("key".into(), [1, 2]),
        Column::new("value".into(), [10, 20]),
    ])?;
    let right_dataframe = DataFrame::new_infer_height(vec![Column::new("key".into(), [2, 3])])?;

    let mut sql_context = SQLContext::new();
    sql_context.register("left_dataframe", left_dataframe.lazy());
    sql_context.register("right_dataframe", right_dataframe.lazy());
    sql_context.execute(query)?.collect()
}

#[test]
fn sql_cte_unqualified_column_should_not_see_join_inputs() {
    // This reproduces why the JSQL join translation qualifies column references with the
    // joined-result CTE name. In standard SQL, the outer query over [join_results] should
    // resolve the unqualified "key" against [join_results]. Polars instead reports it as
    // ambiguous with [right_dataframe."key"], even though [right_dataframe] is scoped only
    // inside the CTE body. Qualifying as [join_results."key"] works around that Polars SQL
    // name-resolution bug.
    let unqualified_query = r#"
        WITH join_results AS (
          SELECT
            CASE WHEN left_dataframe."key" IS NOT NULL THEN
              left_dataframe."key"
            ELSE
              right_dataframe."key"
            END AS "key",
            left_dataframe."value" AS "value"
          FROM (left_dataframe) left_dataframe
          FULL JOIN (right_dataframe) right_dataframe
            ON left_dataframe."key" = right_dataframe."key"
        )
        SELECT "key" AS "key"
        FROM join_results
        WHERE ("key" IS NOT NULL)
        ORDER BY "key" ASC
    "#;

    let qualified_query = r#"
        WITH join_results AS (
          SELECT
            CASE WHEN left_dataframe."key" IS NOT NULL THEN
              left_dataframe."key"
            ELSE
              right_dataframe."key"
            END AS "key",
            left_dataframe."value" AS "value"
          FROM (left_dataframe) left_dataframe
          FULL JOIN (right_dataframe) right_dataframe
            ON left_dataframe."key" = right_dataframe."key"
        )
        SELECT join_results."key" AS "key"
        FROM join_results
        WHERE (join_results."key" IS NOT NULL)
        ORDER BY join_results."key" ASC
    "#;

    check(
        collect_sql(unqualified_query).unwrap_err().to_string(),
        expect![[
            r#""ambiguous reference to column \"key\" (use one of: join_results.\"key\", right_dataframe.\"key\")""#
        ]],
    );

    check(
        collect_sql(qualified_query).unwrap(),
        expect![[r#"
            shape: (3, 1)
            ┌─────┐
            │ key │
            │ --- │
            │ i32 │
            ╞═════╡
            │ 1   │
            │ 2   │
            │ 3   │
            └─────┘"#]],
    );
}

```


